CREATE TABLE IF NOT EXISTS room (id CHAR(36) PRIMARY KEY, name VARCHAR(120) NOT NULL, place VARCHAR(200) NOT NULL, capacity INT NOT NULL, equipment VARCHAR(1000) NOT NULL DEFAULT '', owner_organization_id CHAR(36) NOT NULL, is_bookable TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, CONSTRAINT room_owner_organization_fk FOREIGN KEY (owner_organization_id) REFERENCES organization(id)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS room_addon (id CHAR(36) PRIMARY KEY, name VARCHAR(120) NOT NULL, unit VARCHAR(30) NOT NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS room_booking (id CHAR(36) PRIMARY KEY, reference VARCHAR(32) NOT NULL, room_id CHAR(36) NOT NULL, booker_person_id CHAR(36) NOT NULL, booker_organization_id CHAR(36) NULL, title VARCHAR(200) NOT NULL, attendee_count INT NOT NULL, start_minute INT NOT NULL, end_minute INT NOT NULL, status VARCHAR(16) NOT NULL, decided_by_person_id CHAR(36) NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, UNIQUE KEY room_booking_reference_unique (reference), KEY room_booking_status_index (status, created_at), KEY room_booking_booker_index (booker_person_id, created_at), CONSTRAINT room_booking_room_fk FOREIGN KEY (room_id) REFERENCES room(id), CONSTRAINT room_booking_booker_fk FOREIGN KEY (booker_person_id) REFERENCES person(id)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS room_booking_day (id CHAR(36) PRIMARY KEY, booking_id CHAR(36) NOT NULL, room_id CHAR(36) NOT NULL, booking_date DATE NOT NULL, starts_at DATETIME NOT NULL, ends_at DATETIME NOT NULL, status VARCHAR(16) NOT NULL, released_at DATETIME NULL, KEY room_booking_day_room_time (room_id, status, starts_at, ends_at), KEY room_booking_day_status_time (status, starts_at), KEY room_booking_day_booking (booking_id), CONSTRAINT room_booking_day_booking_fk FOREIGN KEY (booking_id) REFERENCES room_booking(id), CONSTRAINT room_booking_day_room_fk FOREIGN KEY (room_id) REFERENCES room(id)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS room_booking_addon (id CHAR(36) PRIMARY KEY, booking_id CHAR(36) NOT NULL, addon_id CHAR(36) NOT NULL, addon_name VARCHAR(120) NOT NULL, addon_unit VARCHAR(30) NOT NULL, quantity INT NOT NULL, note VARCHAR(500) NULL, KEY room_booking_addon_booking (booking_id), CONSTRAINT room_booking_addon_booking_fk FOREIGN KEY (booking_id) REFERENCES room_booking(id), CONSTRAINT room_booking_addon_addon_fk FOREIGN KEY (addon_id) REFERENCES room_addon(id)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS room_booking_history (id CHAR(36) PRIMARY KEY, booking_id CHAR(36) NOT NULL, actor_person_id CHAR(36) NOT NULL, action VARCHAR(32) NOT NULL, reason VARCHAR(1000) NULL, created_at DATETIME(6) NOT NULL, KEY room_booking_history_booking (booking_id, created_at), CONSTRAINT room_booking_history_booking_fk FOREIGN KEY (booking_id) REFERENCES room_booking(id)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS room_booking_sequence (year INT PRIMARY KEY, last_value INT NOT NULL) DEFAULT CHARSET=utf8mb4;
ALTER TABLE notification ADD COLUMN IF NOT EXISTS target_path VARCHAR(255) NULL
